UIRubbleGroup=function(game){Phaser.Group.call(this,game,null);this.fragmentGroup=this.game.add.group(this);for(var i=0;i<UIConstants.RUBBLE_FRAGMENT_POOL_SIZE;++i){this.fragmentGroup.add(new UIRubbleFragmentSprite(game));}this.emitter=this.add(new UIRubbleEmitter(game));this.log=Log.create('UIRubbleGroup');this.exists=false;this.visible=false;}
UIRubbleGroup.prototype=Object.create(Phaser.Group.prototype);UIRubbleGroup.prototype.constructor=UIRubbleGroup;UIRubbleGroup.prototype.update=function(){if(!this.exists){return;}Phaser.Group.prototype.update.call(this);if(this.countLiving()<=1&&this.fragmentGroup.countLiving()==0){this.exists=false;this.visible=false;}};UIRubbleGroup.prototype.emit=function(tank){if(QualityManager.getQuality()!==QualityManager.QUALITY_SETTINGS.LOW){if(tank.getSpeed()!=0.0||tank.getRotationSpeed()!=0.0){this.exists=true;this.visible=true;var rubbleFragmentSprite=this.fragmentGroup.getFirstExists(false);if(rubbleFragmentSprite){rubbleFragmentSprite.spawn(UIUtils.mpx(tank.getX()),UIUtils.mpx(tank.getY()),tank.getRotation(),tank.getSpeed());}else{}this.emitter.emit(UIUtils.mpx(tank.getX()),UIUtils.mpx(tank.getY()),tank.getRotation(),tank.getSpeed());}}};UIRubbleGroup.prototype.retire=function(){this.exists=false;this.visible=false;this.emitter.retire();this.fragmentGroup.callAll('retire');};